#!/usr/bin/env bash
#
# Sync canonical ABIs and contract addresses from smart-contract-revamp into
# every consumer service (backend-v2, settlement-engine, indexer-v3, frontend-revamp).
#
# Reads:
#   - abi/*.json                                       (generated by export-abi.sh)
#   - deployments/deploy-<network>-latest.json         (hub, generated by run-all.sh)
#   - deployments/deploy-spoke-<chainId>-latest.json   (per spoke chain)
#
# Writes per-service:
#   - <service>/{src/abi,abis}/*.json   (full ABI copies)
#   - <service>/.env.contracts          (regenerated env file with contract addresses)
#     (frontend uses .env.local — Next.js auto-loads it; .env.contracts is not recognized)
#
# Usage:
#   ./bin/sync-to-services.sh [--network=arb-sepolia]
#
# Requires: jq, the abi/ directory populated (run ./bin/export-abi.sh first), and the
# deployment summary file present (run ./bin/run-all.sh first).

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
REPO_ROOT="$(cd "$ROOT_DIR/.." && pwd)"

# ---------- args ----------
NETWORK="arb-sepolia"
for arg in "$@"; do
  case "$arg" in
    --network=*) NETWORK="${arg#*=}" ;;
    -h|--help)
      sed -n '2,/^set -e/p' "$0" | sed 's/^# \{0,1\}//' | head -n 25
      exit 0
      ;;
    *) echo "Unknown arg: $arg" >&2; exit 1 ;;
  esac
done

ABI_DIR="$ROOT_DIR/abi"
HUB_DEPLOY_FILE="$ROOT_DIR/deployments/deploy-${NETWORK}-latest.json"

# Resolve hub chainId from the network slug. Hub deployment JSON has chainId=null
# in current output (see deploy-arb-sepolia-latest.json), so we map it explicitly.
case "$NETWORK" in
  arb-sepolia) HUB_CHAIN_ID=421614 ;;
  anvil)       HUB_CHAIN_ID=31337 ;;
  *)
    # Try reading from deployment JSON as a fallback.
    HUB_CHAIN_ID=$(jq -r '.chainId // empty' "$HUB_DEPLOY_FILE" 2>/dev/null || echo "")
    if [[ -z "$HUB_CHAIN_ID" || "$HUB_CHAIN_ID" == "null" ]]; then
      echo "Error: unknown network '$NETWORK' and chainId not in deployment JSON" >&2
      exit 1
    fi
    ;;
esac

# Spoke chainId → spoke name (matches indexer-v3 env conventions: SPOKE_<NAME>_*).
spoke_name_for() {
  case "$1" in
    84532)    echo "BASE" ;;
    11155111) echo "ETHEREUM" ;;
    97)       echo "BNB" ;;
    80002)    echo "POLYGON" ;;
    *)        echo "" ;;
  esac
}

# ---------- prereqs ----------
command -v jq >/dev/null 2>&1 || { echo "Error: jq is required" >&2; exit 1; }
[[ -d "$ABI_DIR" ]] || { echo "Error: $ABI_DIR does not exist. Run ./bin/export-abi.sh first." >&2; exit 1; }
[[ -f "$HUB_DEPLOY_FILE" ]] || { echo "Error: $HUB_DEPLOY_FILE does not exist. Run ./bin/run-all.sh first." >&2; exit 1; }

ABI_COUNT=$(find "$ABI_DIR" -maxdepth 1 -name '*.json' | wc -l | tr -d ' ')
[[ "$ABI_COUNT" -gt 0 ]] || { echo "Error: no ABI files in $ABI_DIR" >&2; exit 1; }

echo "Syncing network=$NETWORK (hub chainId=$HUB_CHAIN_ID)"
echo "  Hub deployment: ${HUB_DEPLOY_FILE#$REPO_ROOT/}"
echo "  ABI source:     ${ABI_DIR#$REPO_ROOT/} ($ABI_COUNT files)"
echo ""

# ---------- service paths ----------
BACKEND_DIR="$REPO_ROOT/backend-v2"
SETTLEMENT_DIR="$REPO_ROOT/settlement-engine"
INDEXER_DIR="$REPO_ROOT/indexer-v3"
FRONTEND_DIR="$REPO_ROOT/frontend-revamp"

# ---------- pull hub addresses ----------
get_addr() {
  jq -r ".$1 // empty" "$HUB_DEPLOY_FILE"
}

BALANCE_LEDGER=$(get_addr balanceLedgerAddress)
CENTUARI=$(get_addr centuariAddress)
HUB_DEPOSITOR=$(get_addr hubDepositorAddress)
COLLATERAL_MANAGER=$(get_addr collateralManagerAddress)
SETTLEMENT_PROXY=$(get_addr settlementProxy)
WITHDRAWAL_REGISTRY=$(get_addr withdrawalRegistryAddress)
HUB_INTENT_SETTLER=$(get_addr hubIntentSettlerAddress)
SETTLEMENT_LEDGER=$(get_addr settlementLedgerAddress)
BOND_TOKEN_FACTORY=$(get_addr bondTokenFactoryAddress)
# Prefer the real (Phase 3 / C6) RiskModule address; fall back to the Phase 1 stub.
RISK_MODULE=$(get_addr riskModuleAddress)
[[ -z "$RISK_MODULE" || "$RISK_MODULE" == "null" ]] && RISK_MODULE=$(get_addr riskModuleStubAddress)
FAUCET=$(get_addr faucetAddress)
FAUCET_TOKENS_CSV=$(get_addr faucetTokensRaw)

# ---------- helpers ----------
# Emit `VAR=value`; skip with a comment when the value is missing / null / zero address.
emit() {
  local name="$1" value="$2"
  if [[ -n "$value" && "$value" != "null" && "$value" != "0x0000000000000000000000000000000000000000" ]]; then
    printf '%s=%s\n' "$name" "$value"
  else
    printf '# %s=  # not present in deployment summary (contract not deployed?)\n' "$name"
  fi
}

write_header() {
  local out="$1"
  cat > "$out" <<EOF
# AUTO-GENERATED by smart-contract-revamp/bin/sync-to-services.sh — DO NOT EDIT BY HAND.
# Source: ${HUB_DEPLOY_FILE#$REPO_ROOT/}
# Network: $NETWORK   Hub chainId: $HUB_CHAIN_ID
# Regenerate with: cd smart-contract-revamp && ./bin/sync-to-services.sh

EOF
}

copy_abis() {
  local dst="$1"
  mkdir -p "$dst"
  # Wipe stale files in dst that don't exist in source, then copy fresh.
  find "$dst" -maxdepth 1 -name '*.json' -delete 2>/dev/null || true
  cp "$ABI_DIR"/*.json "$dst/"
  local n
  n=$(find "$dst" -maxdepth 1 -name '*.json' | wc -l | tr -d ' ')
  echo "  copied $n ABI files → ${dst#$REPO_ROOT/}"
}

# ---------- per-service sync ----------

# backend-v2
if [[ -d "$BACKEND_DIR" ]]; then
  echo "=== backend-v2 ==="
  copy_abis "$BACKEND_DIR/src/abi"
  out="$BACKEND_DIR/.env.contracts"
  write_header "$out"
  {
    echo "DEPOSIT_CHAIN_ID=$HUB_CHAIN_ID"
    emit HUB_DEPOSITOR_ADDRESS         "$HUB_DEPOSITOR"
    emit BALANCE_LEDGER_ADDRESS        "$BALANCE_LEDGER"
    emit CENTUARI_ADDRESS              "$CENTUARI"
    emit COLLATERAL_MANAGER_ADDRESS    "$COLLATERAL_MANAGER"
    emit RISK_MODULE_ADDRESS           "$RISK_MODULE"
    emit WITHDRAWAL_REGISTRY_ADDRESS   "$WITHDRAWAL_REGISTRY"
    emit "FAUCET_ADDRESS_${HUB_CHAIN_ID}" "$FAUCET"
    emit "FAUCET_TOKENS_${HUB_CHAIN_ID}"  "$FAUCET_TOKENS_CSV"
  } >> "$out"
  echo "  wrote ${out#$REPO_ROOT/}"
  echo ""
else
  echo "Skipping backend-v2 (directory not found: $BACKEND_DIR)"
fi

# settlement-engine
if [[ -d "$SETTLEMENT_DIR" ]]; then
  echo "=== settlement-engine ==="
  copy_abis "$SETTLEMENT_DIR/src/abi"
  out="$SETTLEMENT_DIR/.env.contracts"
  write_header "$out"
  {
    emit SETTLEMENT_CONTRACT_ADDRESS "$SETTLEMENT_PROXY"
  } >> "$out"
  echo "  wrote ${out#$REPO_ROOT/}"
  echo ""
else
  echo "Skipping settlement-engine (directory not found: $SETTLEMENT_DIR)"
fi

# indexer-v3 — hub + all spokes
if [[ -d "$INDEXER_DIR" ]]; then
  echo "=== indexer-v3 ==="
  copy_abis "$INDEXER_DIR/src/abi"
  out="$INDEXER_DIR/.env.contracts"
  write_header "$out"
  {
    echo "# Hub addresses"
    emit BALANCE_LEDGER_ADDRESS        "$BALANCE_LEDGER"
    emit CENTUARI_ADDRESS              "$CENTUARI"
    emit HUB_DEPOSITOR_ADDRESS         "$HUB_DEPOSITOR"
    emit COLLATERAL_MANAGER_ADDRESS    "$COLLATERAL_MANAGER"
    emit WITHDRAWAL_REGISTRY_ADDRESS   "$WITHDRAWAL_REGISTRY"
    emit HUB_INTENT_SETTLER_ADDRESS    "$HUB_INTENT_SETTLER"
    emit SETTLEMENT_LEDGER_ADDRESS     "$SETTLEMENT_LEDGER"
    emit BOND_TOKEN_FACTORY_ADDRESS    "$BOND_TOKEN_FACTORY"
    echo ""
    echo "# Spoke addresses (per chain)"
    for chain_id in 84532 11155111 97 80002; do
      spoke_file="$ROOT_DIR/deployments/deploy-spoke-${chain_id}-latest.json"
      spoke_name=$(spoke_name_for "$chain_id")
      if [[ -z "$spoke_name" ]]; then
        echo "# (chain $chain_id has no canonical SPOKE_<NAME> mapping)"
        continue
      fi
      if [[ -f "$spoke_file" ]]; then
        gateway=$(jq -r '.contracts.SpokeDepositGateway.proxy // empty' "$spoke_file")
        vault=$(jq -r '.contracts.SpokeVaultStable.proxy // empty' "$spoke_file")
        emit "SPOKE_${spoke_name}_DEPOSIT_GATEWAY_ADDRESS" "$gateway"
        emit "SPOKE_${spoke_name}_VAULT_STABLE_ADDRESS"    "$vault"
      else
        echo "# $spoke_name spoke (chainId $chain_id) not deployed yet (missing ${spoke_file#$REPO_ROOT/})"
      fi
    done
  } >> "$out"
  echo "  wrote ${out#$REPO_ROOT/}"
  echo ""
else
  echo "Skipping indexer-v3 (directory not found: $INDEXER_DIR)"
fi

# frontend-revamp — Next.js, uses .env.local + NEXT_PUBLIC_ prefix
if [[ -d "$FRONTEND_DIR" ]]; then
  echo "=== frontend-revamp ==="
  copy_abis "$FRONTEND_DIR/abis"
  out="$FRONTEND_DIR/.env.local"
  write_header "$out"
  {
    echo "NEXT_PUBLIC_CHAIN_ID=$HUB_CHAIN_ID"
    emit NEXT_PUBLIC_HUB_DEPOSITOR_ADDRESS      "$HUB_DEPOSITOR"
    emit NEXT_PUBLIC_BALANCE_LEDGER_ADDRESS     "$BALANCE_LEDGER"
    emit NEXT_PUBLIC_CENTUARI_ADDRESS           "$CENTUARI"
    emit NEXT_PUBLIC_COLLATERAL_MANAGER_ADDRESS "$COLLATERAL_MANAGER"
    emit "NEXT_PUBLIC_FAUCET_ADDRESS_${HUB_CHAIN_ID}" "$FAUCET"
  } >> "$out"
  echo "  wrote ${out#$REPO_ROOT/}"

  # Token allowlist — write addresses-only JSON consumed by src/lib/token-config.ts.
  # Trust anchor for "which ERC20 contracts the frontend will touch"; symbol keys are
  # for human review only, runtime trust is address-only.
  tokens_json="$FRONTEND_DIR/config/tokens.json"
  mkdir -p "$(dirname "$tokens_json")"
  existing="{}"
  if [[ -f "$tokens_json" ]]; then
    existing=$(cat "$tokens_json")
  fi
  mock_tokens=$(jq '.mockTokens // {}' "$HUB_DEPLOY_FILE")
  now=$(date -u +"%Y-%m-%dT%H:%M:%SZ")

  # Build the new content with a placeholder timestamp first, so we can detect
  # whether the substantive payload actually changed and avoid timestamp churn.
  build_payload() {
    local stamp="$1"
    jq -n \
      --argjson existing "$existing" \
      --argjson mock_tokens "$mock_tokens" \
      --arg chain_id "$HUB_CHAIN_ID" \
      --arg network "$NETWORK" \
      --arg stamp "$stamp" \
      '
      ($existing // {}) as $base
      | $base
      | ._meta = {
          "generated_by": "smart-contract-revamp/bin/sync-to-services.sh",
          "source": ("smart-contract-revamp/deployments/deploy-" + $network + "-latest.json (mockTokens)"),
          "last_updated": $stamp,
          "warning": "Auto-generated. Review the diff before committing. Symbol keys exist for human review only — runtime trust is address-only."
        }
      | .[$chain_id] = $mock_tokens
      '
  }

  new_compare=$(build_payload "PLACEHOLDER")
  old_compare=""
  if [[ -f "$tokens_json" ]]; then
    old_compare=$(jq '._meta.last_updated = "PLACEHOLDER"' "$tokens_json" 2>/dev/null || echo "")
  fi
  if [[ "$new_compare" != "$old_compare" ]]; then
    build_payload "$now" > "$tokens_json"
    echo "  wrote ${tokens_json#$REPO_ROOT/} (updated)"
    if git -C "$FRONTEND_DIR" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
      git -C "$FRONTEND_DIR" --no-pager diff -- config/tokens.json || true
    fi
  else
    echo "  ${tokens_json#$REPO_ROOT/} unchanged"
  fi
  echo ""
else
  echo "Skipping frontend-revamp (directory not found: $FRONTEND_DIR)"
fi

echo "Done."
